// Package requestid generates the per-request id and carries it in a context.
// The id is always generated by the server. It is never taken from a client
// header and never derived from the trace id.
package requestid

import (
	"context"
	"crypto/rand"
	"encoding/hex"
)

// Header is the response header that echoes the id, so a caller can quote it.
const Header = "X-Request-Id"

// New returns a random 32-hex request id.
func New() string {
	var b [16]byte
	_, _ = rand.Read(b[:]) // crypto/rand.Read never returns an error (Go ≥ 1.24)
	return hex.EncodeToString(b[:])
}

type ctxKey struct{}

// NewContext returns ctx carrying id.
func NewContext(ctx context.Context, id string) context.Context {
	return context.WithValue(ctx, ctxKey{}, id)
}

// FromContext returns the request id in ctx, or "" outside a request.
func FromContext(ctx context.Context) string {
	id, _ := ctx.Value(ctxKey{}).(string)
	return id
}
